import {Suspense, useCallback} from 'react'
import {EntryPointContainer} from 'react-relay'

import {useEntryPointLoaderWithEnvironment} from '../../../../../hooks/relay/useEntryPointLoaderWithEnvironment'
import {useSlice} from '../../../../../hooks/useSlice'
import PageTitle from '../../../../common/PageTitle/PageTitle'

import {CleanupFormEntryPoint} from './CleanupForm/CleanupForm.entryPoint'
import type {Props, RuleId} from './Rules.types'
import RulesList from './RulesList/RulesList.container'

type State = {
  showForm: boolean
  currentRuleId: RuleId | null
}
const initialState: State = {
  showForm: false,
  currentRuleId: null,
}
const reducers = {
  openRuleForm: (state: State, ruleId?: RuleId | null) => ({
    showForm: true,
    currentRuleId: ruleId?.length ? ruleId : state.currentRuleId,
  }),
  closeForm: (_: State, __: void) => initialState,
}

function Rules({
  holderNode,
  inheritedVisible,
  projectId,
  embedded = false,
  hideOwn = false,
  hideInherited = false,
  hideEnforced = false,
  readOnlyProjectsKey,
}: Props) {
  const [{showForm, currentRuleId}, {openRuleForm, closeForm}] = useSlice(reducers, initialState)
  const [entryPoint, loadEntryPoint, disposeEntryPoint] =
    useEntryPointLoaderWithEnvironment(CleanupFormEntryPoint)
  const doOpenRuleForm = useCallback(
    (ruleId?: RuleId | null) => {
      loadEntryPoint(holderNode)
      openRuleForm(ruleId)
    },
    [openRuleForm, loadEntryPoint, holderNode],
  )
  const doCloseForm = useCallback(() => {
    disposeEntryPoint()
    closeForm()
  }, [closeForm, disposeEntryPoint])
  return (
    <>
      {embedded ? null : <PageTitle>{'Clean-up Rules'}</PageTitle>}
      <Suspense>
        <RulesList
          projectId={projectId}
          onRuleOpenClick={doOpenRuleForm}
          holderNode={holderNode}
          inheritedVisible={inheritedVisible}
          embedded={embedded}
          hideOwn={hideOwn}
          hideInherited={hideInherited}
          hideEnforced={hideEnforced}
          readOnlyProjectsKey={readOnlyProjectsKey}
        />
      </Suspense>
      {showForm && entryPoint && (
        <Suspense>
          <EntryPointContainer
            entryPointReference={entryPoint}
            props={{
              projectId,
              holderNode,
              ruleId: currentRuleId,
              onCancel: doCloseForm,
              onComplete: doCloseForm,
              readOnlyProjectsKey,
            }}
          />
        </Suspense>
      )}
    </>
  )
}

export default Rules
