import {fetchProjectWithAllParentsData} from '../../../../../../../actions/projects'
import {getBuildTypeArg} from '../../../../../../../rest/buildTypes'
import {
  getBuildType,
  getFullPath,
  getProject,
  isBuildTypeLoaded,
  isProjectLoaded,
} from '../../../../../../../selectors'
import {restApi} from '../../../../../../../services/rest'
import {getProjectBuildTypeFilter, ROOT_PROJECT_ID} from '../../../../../../../types'
import type {BuildTypeId, ProjectId} from '../../../../../../../types'
import {notNull} from '../../../../../../../utils/guards'
import {getItemKey, SEPARATOR} from '../../../../../../common/BuildPath/BuildPath'
import pathStyles from '../../../../../../common/BuildPath/BuildPath.module.css'
import Popup from '../../../../../../common/Popup/Popup.lazy'
import ProjectOrBuildTypeIcon from '../../../../../../common/ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon'
import {EntityIconType} from '../../../../../../common/ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon.types'
import type {CleanupProjectPageUseIsReadOnlyFragment$key} from '../../../../__generated__/CleanupProjectPageUseIsReadOnlyFragment.graphql'
import {useIsReadOnly} from '../../../../CleanupProjectPage.hooks'
import {shouldPreventClickOnRow} from '../../../Listing.utils'
import type {CleanupHolderNode, RuleId, Rule as RuleType} from '../../Rules.types'
