import type {EntryPoint} from 'react-relay'
import {getRequest} from 'relay-runtime'

import {Policy} from '../../../../../../rest/branches'
import {makeResource} from '../../../../../../utils/makeResource'
import {
  branchesQuery,
  getBranchesQueryVariables,
} from '../../../../../common/BranchSelect/BranchSelect.queries'
import type {CleanupHolderNode} from '../Rules.types'

import type {CleanupFormOuterContainerComponent} from './CleanupForm.container'
import {buildTypeTagsQuery} from './CleanupForm.queries'

export const CleanupFormEntryPoint: EntryPoint<
  CleanupFormOuterContainerComponent,
  CleanupHolderNode
> = {
  root: makeResource(
    'CleanupForm',
    () => import(/* webpackChunkName: "CleanupForm" */ './CleanupForm.container'),
  ),
  getPreloadProps: node => ({
    queries: {
      branches: {
        parameters: getRequest(branchesQuery),
        variables: getBranchesQueryVariables({
          node,
          policy: Policy.ALL_BRANCHES,
        }),
      },
      buildTypeTags: {
        parameters: getRequest(buildTypeTagsQuery),
        variables:
          node.nodeType === 'bt'
            ? {btLocator: `id:${node.id}`, skip: false}
            : {btLocator: '', skip: true},
      },
    },
  }),
}
